def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    candidates=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,5):
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if (dr or dc) and 0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==5:
                            candidates.append((r,c,dr,dc))
    if not candidates: return out
    r,c,dr,dc=candidates[0]
    color=grid[r][c]
    for i in range(h):
        for j in range(w):
            if out[i][j]==5: out[i][j]=0
    out[r][c]=0
    seen=set()
    while (r,c,dr,dc) not in seen:
        seen.add((r,c,dr,dc))
        if not 0<=r+dr<h: dr=-dr
        if not 0<=c+dc<w: dc=-dc
        nr,nc=r+dr,c+dc
        if not(0<=nr<h and 0<=nc<w) or out[nr][nc]!=0: break
        r,c=nr,nc
    out[r][c]=color
    return out

